"""Generate Orekit 12.2 reference states for the opt-in tesseral Cowell tier (RM-09).

ORACLE
------
Orekit 12.2 (CS GROUP, Apache-2.0) + Hipparchus 3.1, run as a separate program:
NumericalPropagator + DormandPrince853, HolmesFeatherstoneAttractionModel over the
EGM2008 field truncated to degree/order N (read from the committed
tools/egm2008_to70.gfc, the same file kshana's bundled table was generated from),
plus NewtonianAttraction with the field's own GM (Orekit's Holmes-Featherstone
model excludes the central term). Optional tiers add kshana's own Sun/Moon series
as third bodies and cannonball SRP, exactly as in numerical_cowell_propagator.

The gravity body frame is a rotation about the inertial z axis by the IAU 2000
Earth rotation angle at UT1 = TT (kshana src/cio.rs earth_rotation_angle, ported
verbatim into TesseralDriver.java), evaluated at kshana's advanced epoch
epoch_jd_tt + t/86400. This is kshana's EarthFixedFrame::Era convention. The
comparison therefore validates the tesseral field evaluation, its rotation
plumbing and the integration; it does NOT validate Earth-orientation fidelity
(precession-nutation, polar motion, UT1-UTC), which both sides omit here.

REPRODUCE
---------
  source /root/kshana-oracles/orekit/cp.sh     # OREKIT_CP, OREKIT_DATA
  (cd java && javac -cp "$OREKIT_CP" TesseralDriver.java)
  /root/kshana-oracles/.venv/bin/python generate_cowell_tesseral_orekit_oracle.py \
      > cowell_tesseral_orekit_oracle.txt
"""

import json
import math
import os
import subprocess
import sys

HERE = os.path.dirname(os.path.abspath(__file__))
JAVA_DIR = os.path.join(HERE, "java")
GFC = os.path.normpath(os.path.join(HERE, "..", "..", "..", "tools", "egm2008_to70.gfc"))
GM = 3.986004415e14  # EGM2008 GM (the field's own; header of the .gfc)
RE = 6378137.0
ARC_SECONDS = 86400.0
N_EPOCHS = 25
TOL = 1e-11
EPOCH_J2000 = 2451545.0
EPOCH_2026 = 2461041.5  # 2026-01-01 00:00 TT


def run_driver(req):
    cp = ".:" + os.environ["OREKIT_CP"]
    p = subprocess.run(["java", "-cp", cp, "TesseralDriver"], input=json.dumps(req),
                       capture_output=True, text=True, cwd=JAVA_DIR, env=dict(os.environ))
    if p.returncode != 0:
        sys.stderr.write(p.stdout + p.stderr)
        raise RuntimeError(f"TesseralDriver failed for {req['tier']}")
    return p.stdout


def circular(alt_m, inc_deg):
    a = RE + alt_m
    v = math.sqrt(GM / a)
    inc = math.radians(inc_deg)
    return [a, 0.0, 0.0], [0.0, v * math.cos(inc), v * math.sin(inc)]


def gto():
    rp, ra = RE + 400e3, 42164e3
    a = 0.5 * (rp + ra)
    vp = math.sqrt(GM * (2.0 / rp - 1.0 / a))
    inc = math.radians(28.5)
    return [rp, 0.0, 0.0], [0.0, vp * math.cos(inc), vp * math.sin(inc)]


CASES = [
    # tier, regime, nmax, epoch, (r0, v0), third_body, srp
    ("G8", "LEO", 8, EPOCH_J2000, circular(621863.0, 45.0), 0, 0),
    ("G70", "LEO", 70, EPOCH_J2000, circular(621863.0, 45.0), 0, 0),
    ("G70", "POLAR", 70, EPOCH_2026, circular(500e3, 89.9), 0, 0),
    ("G70", "SSO", 70, EPOCH_2026, circular(700e3, 98.2), 0, 0),
    ("G70", "GTO", 70, EPOCH_J2000, gto(), 0, 0),
    ("G70P", "LEO", 70, EPOCH_2026, circular(621863.0, 45.0), 1, 1),
]


def main():
    print("# Orekit 12.2 (Apache-2.0) NumericalPropagator + DormandPrince853 reference states,")
    print("# HolmesFeatherstone EGM2008 N x N in an ERA-rotating Earth frame (UT1 = TT).")
    print("# Generated by generate_cowell_tesseral_orekit_oracle.py (see its docstring).")
    print("# Field: tools/egm2008_to70.gfc (GM=3.986004415e14, Re=6378136.3, tide-free).")
    print("# Tiers: G8 = EGM2008 8x8; G70 = 70x70; G70P = 70x70 + Sun/Moon (kshana series) + SRP.")
    print("# CASE line:  CASE <tier> <regime> | nmax | epoch_jd_tt | r0 | v0 | third_body | srp | cr | area_over_mass")
    print("# STATE line: STATE <tier> <regime> <k> <t_s> | rx,ry,rz (m) | vx,vy,vz (m/s)")
    for tier, regime, nmax, epoch, (r0, v0), tb, srp in CASES:
        req = dict(r0=r0, v0=v0, epoch_jd_tt=epoch, tier=tier, cr=1.5, area_over_mass=0.02,
                   cd_area_over_mass=0.0, arc_seconds=ARC_SECONDS, n_epochs=N_EPOCHS,
                   tol=TOL, nmax=nmax, gfc=GFC, third_body=tb, srp=srp)
        raw = run_driver(req)
        print("CASE {} {} | {} | {!r} | {:.17e},{:.17e},{:.17e} | {:.17e},{:.17e},{:.17e} | {} | {} | 1.5 | 0.02"
              .format(tier, regime, nmax, epoch, *r0, *v0, tb, srp))
        for line in raw.splitlines():
            if line.startswith("STATE "):
                p = line.split()
                print(f"STATE {p[1]} {regime} {p[2]} {p[3]} | {p[4]} | {p[5]}")


if __name__ == "__main__":
    main()
